import os

def safe_upload_path(upload_dir: str, filename: str) -> str:
    if not upload_dir or not filename:
        raise ValueError("upload_dir and filename must be provided")

    safe_filename = os.path.basename(filename)
    safe_path = os.path.join(upload_dir, safe_filename)

    if not os.path.isabs(safe_path):
        raise ValueError(f"Path {safe_path} is not absolute")

    if not safe_path.startswith(upload_dir):
        raise ValueError(f"Path {safe_path} escapes {upload_dir}")

    return safe_path
```

